package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.core.*;import net.minecraft.server.level.*;import net.minecraft.world.damagesource.*;import net.minecraft.world.entity.*;import net.minecraft.world.level.*;import net.minecraft.world.phys.*;import net.minecraft.tags.DamageTypeTags;import java.util.*;
/** One pre-injury damage hook. Cover is actual remaining material intersecting the source-to-body rays. */
public final class Ps01Protection{
 public record Cover(BlockPos root,Direction face,int door,double shellHealth,double doorHealth){}
 public static final class Blast{final ServerLevel level;final Vec3 origin;final float radius;final long time;final List<Cover> covers;final Map<BlockPos,Ps01BlockEntity> proposed=new HashMap<>();final Set<BlockPos> allowedBody=new HashSet<>(),allowedDoor=new HashSet<>();Blast(ServerLevel l,Vec3 o,float r,List<Cover> c){level=l;origin=o;radius=r;time=l.getGameTime();covers=c;}}
 private static final Map<DamageSource,Blast> SOURCES=new WeakHashMap<>();private static final Map<Explosion,Blast> EVENTS=new WeakHashMap<>();private static final ArrayDeque<Blast>PENDING=new ArrayDeque<>();
 public static List<Ps01BlockEntity> near(ServerLevel l,AABB box){var query=new Ps01WorldData.AABBQuery(((int)Math.floor(box.minX))>>4,((int)Math.floor(box.minZ))>>4,((int)Math.floor(box.maxX))>>4,((int)Math.floor(box.maxZ))>>4);var out=new ArrayList<Ps01BlockEntity>();for(var entry:Ps01WorldData.get(l).near(query))if(l.hasChunkAt(entry.root)&&l.getBlockEntity(entry.root)instanceof Ps01BlockEntity b&&!b.isRemoved()&&b.getRenderBoundingBox().intersects(box))out.add(b);return out;}
 private static Cover cover(Ps01BlockEntity b){return new Cover(b.getBlockPos(),b.facing(),b.doorStep(),b.integrity(),b.doorIntegrity());}
 public static void prepare(ServerLevel l,Explosion e,List<BlockPos> blocks){Pb01Protection.prepare(l,e,blocks);Vec3 origin=e.getPosition();float radius=((nl.smartstreamlabs.sbwdroneconfig.mixin.RubbleExplosionAccess)e).rubble$radius();double reach=Math.min(64,Math.max(1,radius*2));var candidates=near(l,new AABB(origin,origin).inflate(reach));var covers=new ArrayList<Cover>();var context=new Blast(l,origin,radius,covers);int count=0;
  for(var b:candidates){if(count++>=Ps01Config.MAX_BLAST_SHELTERS.get())break;covers.add(cover(b));if(Ps01Config.BLAST_WEAR.get()<=0||!l.getGameRules().getBoolean(net.minecraft.world.level.GameRules.RULE_MOBGRIEFING)&&(e.getDirectSourceEntity()instanceof net.minecraft.world.entity.Mob||e.getIndirectSourceEntity()instanceof net.minecraft.world.entity.Mob))continue;for(var p:Ps01WorldData.all(b.facing(),b.getBlockPos())){if(!l.hasChunkAt(p)||Vec3.atCenterOf(p).distanceToSqr(origin)>(reach+1)*(reach+1))continue;var state=l.getBlockState(p);if(state.getBlock()instanceof Ps01Block&&!state.getCollisionShape(l,p).isEmpty()){context.proposed.put(p,b);if(!blocks.contains(p))blocks.add(p);}}}
  if(SOURCES.size()>256)SOURCES.entrySet().removeIf(v->v.getValue().level!=l||v.getValue().time<l.getGameTime()-2);SOURCES.put(((nl.smartstreamlabs.sbwdroneconfig.mixin.Vc01ExplosionAccess)e).vc01$source(),context);EVENTS.put(e,context);
 }
 public static void finish(Explosion e,List<BlockPos> blocks){Pb01Protection.finish(e,blocks);var context=EVENTS.remove(e);if(context==null)return;var approved=new HashSet<BlockPos>(blocks);var denied=new HashSet<BlockPos>();for(var entry:context.proposed.entrySet())if(!approved.contains(entry.getKey()))denied.add(entry.getValue().getBlockPos());for(var p:blocks){var b=context.proposed.get(p);if(b==null||denied.contains(b.getBlockPos()))continue;var s=context.level.getBlockState(p);if(!(s.getBlock()instanceof Ps01Block))continue;var hit=Ps01Geometry.local(b.getBlockPos(),b.facing(),Vec3.atCenterOf(p));context.allowedBody.add(b.getBlockPos());if(((Ps01Block)s.getBlock()).door&&b.doorHealth>0){for(var leaf:Ps01Geometry.leaf(b.doorStep())){var center=leaf.getCenter();if(!Ps01Geometry.shellBetween(Ps01Geometry.local(b.getBlockPos(),b.facing(),context.origin),center)){context.allowedDoor.add(b.getBlockPos());break;}}}}
  blocks.removeIf(p->context.level.getBlockState(p).getBlock()instanceof Ps01Block);if(PENDING.size()<256)PENDING.add(context);
 }
 public static void tick(){Pb01Protection.tick();while(!PENDING.isEmpty()){var blast=PENDING.removeFirst();var roots=new HashSet<BlockPos>(blast.allowedBody);roots.addAll(blast.allowedDoor);for(var root:roots){if(!blast.level.hasChunkAt(root)||!(blast.level.getBlockEntity(root)instanceof Ps01BlockEntity b))continue;double distance=Math.sqrt(b.getRenderBoundingBox().distanceToSqr(blast.origin));double amount=Math.min(Ps01Config.HEALTH.get()*.20,Ps01Config.BLAST_WEAR.get()*blast.radius*Math.max(0,1-distance/Math.max(1,blast.radius*2)));if(blast.allowedDoor.contains(root))b.hit(amount,true,blast.origin);if(blast.allowedBody.contains(root)&&!b.isRemoved())b.hit(amount,false,blast.origin);}}}
 public static boolean explosion(DamageSource s){return s.is(DamageTypeTags.IS_EXPLOSION)||s.typeHolder().unwrapKey().map(k->k.location().getPath().contains("explosion")).orElse(false);}
 public static boolean projectile(DamageSource s){return s.is(DamageTypeTags.IS_PROJECTILE)||s.getDirectEntity()instanceof net.minecraft.world.entity.projectile.Projectile||com.atsuishio.superbwarfare.tools.DamageTypeTool.isGunDamage(s);}
 public static float reduce(LivingEntity player,DamageSource source,float damage){if(!(player.level()instanceof ServerLevel l)||!(player instanceof net.minecraft.world.entity.player.Player)||!(damage>0)||!explosion(source)&&!projectile(source))return damage;var blast=SOURCES.get(source);boolean known=blast!=null&&blast.level==l&&blast.time>=l.getGameTime()-2;Vec3 start=known?blast.origin:source.getSourcePosition();if(!explosion(source)&&source.getDirectEntity()!=null){var n=source.getDirectEntity().getPersistentData();if(n.contains("PsCoverTime")&&n.getLong("PsCoverTime")>=l.getGameTime()-2)start=new Vec3(n.getDouble("PsCoverX"),n.getDouble("PsCoverY"),n.getDouble("PsCoverZ"));}if(start==null)return damage;List<Cover> covers=known?blast.covers:near(l,player.getBoundingBox().inflate(8)).stream().map(Ps01Protection::cover).toList();double reduction=0;var box=player.getBoundingBox();double h=box.getYsize(),w=box.getXsize();var samples=new Vec3[]{player.position().add(0,h*.5,0),player.position().add(0,h*.9,0),player.position().add(0,h*.14,0),player.position().add(w*.38,h*.55,0),player.position().add(-w*.38,h*.55,0)};
  for(var c:covers){double shell=(explosion(source)?Ps01Config.BLAST.get():Ps01Config.FRAGMENT.get())*c.shellHealth;double door=(explosion(source)?Ps01Config.DOOR_BLAST.get():Ps01Config.DOOR_FRAGMENT.get())*c.doorHealth;double least=1;var a=Ps01Geometry.local(c.root,c.face,start);for(var end:samples)least=Math.min(least,Ps01Geometry.cover(a,Ps01Geometry.local(c.root,c.face,end),c.door,shell,door));reduction=Math.max(reduction,least);}
  return Math.min((float)(damage*(1-Math.min(.99,reduction))),Pb01Protection.reduce(player,source,damage));
 }
 public static void reset(){SOURCES.clear();EVENTS.clear();PENDING.clear();Pb01Protection.reset();}
 private Ps01Protection(){}
}
